        let residue_cost = if remainder == 0.0 {
            0.0
        } else if remainder <= next_u / 4.0 {
            0.42
        } else if remainder >= next_u * 0.75 {
            0.86
        } else {
            1.0
        };
        score += 35.0 * residue_cost * (1.0 - 0.35 * progress);

        let next_after = post - next_u;
        if next_after > 0.0 {
            let second_rem = next_after % item_u;
            if second_rem == 0.0 {
                score -= 17.0 * (0.45 + 0.55 * progress);
            } else {
                let sliver = second_rem.min(item_u - second_rem) / item_u;
                score += 34.0 * sliver * (0.4 + 0.6 * progress);
            }
        }

        let closure = if (post - next_u).abs() < 0.5 {
            1.0
        } else if (post - next_u).abs() <= item_u * 0.15 {
            0.55
        } else {
            0.0
        };
        score -= 29.0 * closure * (0.45 + 0.55 * progress);

        if remainder <= next_u * 0.12 {
            score -= 10.0 * (0.5 + 0.5 * progress);
        }
    }

    // New bins are penalized when viable existing residuals remain, but the
    // pressure decreases as the stream advances and choices become richer.
    if is_new && fitting_bins_count > 0 {
        let tight = (fitting_bins_count as f64).min(4.0) / 4.0;
        score += 52.0 * tight * (1.0 - 0.50 * progress);
        score -= 21.0 * norm_item * norm_item * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let capacity = bin_capacity.max(1) as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;
    let post = post_residual as f64;
    let mean = mean_residual.max(0.0);
    let progress = if total_items == 0 {
        0.0
    } else {
        (step_index as f64 / total_items as f64).min(1.0)
    };

    // Small gaps are much less useful than a fragmented but recoverable tail.
    let dead_space_penalty = if post < next && next > 0.0 {
        (next - post).max(0.0) * 2.5
    } else if post < 10.0 {
        (10.0 - post) * 1.8
    } else {
        0.0
    };
    score += dead_space_penalty;

    // Prefer tighter fits, but do not make a near-perfect fit dominate a valid one.
    score += (post / capacity) * 3.0;

    // Reward bins whose remaining space is close to the typical future need.
    if next > 0.0 {
        score += (post - next).abs() / capacity * 1.25;
    }

    // The final item should be placed in the emptiest available bin.
    if next == 0.0 {
        score += post / capacity * 2.0;
    }

    // Pressure to consolidate when many bins are already open.
    let pressure = (open_bins_count as f64).min(1000.0);
    score += pressure * 0.035;

    // If this is the only fitting bin, avoid creating a new bin.
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // Late in the stream, favor closing bins and reducing fragmentation.
    score += progress * (post / capacity) * 1.5;

    // Keep the score centered while retaining the dead-space signal.
    score -= mean.min(capacity) * 0.015;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
