        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    };
    let is_new = bin_residual == bin_capacity;
    let norm_post = (post / capacity).clamp(0.0, 1.0);
    let norm_item = (item / capacity).clamp(0.0, 1.0);
    let norm_mean = (mean / capacity).clamp(0.0, 1.0);
    let norm_next = (next / capacity).clamp(0.0, 1.0);

    let mut score = post;

    if post_residual == 0 {
        score -= 245.0 + 85.0 * progress + 42.0 * norm_item;
    } else {
        score += 135.0 * norm_post * (1.0 - 0.35 * progress);

        let next_compatible = next > 0.0 && post >= next;
        if next_compatible {
            let alignment = 1.0 - (post - next) / capacity;
            score -= 46.0 * alignment;
            let remainder = if next > 0.0 { post % next } else { post };
            if remainder == 0.0 {
                score -= 28.0;
            } else if remainder <= next / 3.0 {
                score -= 13.0;
            }
        } else if next > 0.0 {
            score += 11.0 * (next - post).min(next) / capacity;
        }

        let item_remainder = post % item.max(1.0);
        if post < item {
            score += 96.0 * (item - post) / capacity;
        } else {
            score -= 17.0 * (post / item.max(1.0)).min(8.0);
            if item_remainder == 0.0 {
                score -= 23.0;
            } else if item_remainder <= item / 3.0 {
