        let pool_pressure = if fitting_bins_count == 0 {
            1.0
        } else {
            (fitting_bins_count as f64 / open_bins_count.max(1) as f64).min(1.0)
        };
        score += 58.0 + 82.0 * progress + 38.0 * pool_pressure;
        score += 24.0 * norm_item;
        if progress > 0.82 && fitting_bins_count > 1 {
            score += 48.0;
        }
    }

    let scarcity = norm_mean;
    score -= 34.0 * scarcity * norm_item;
    score += 16.0 * progress * (1.0 - scarcity);

    if fitting_bins_count == 1 && !is_new {
        score += 25.0 + 60.0 * progress;
        score += 2.2 * post;
        if post > 0.0 && post < next {
            score += 15.0;
        }
    }

    if open_bins_count > 2 && !is_new {
        let extra = (open_bins_count as f64 - 2.0).min(6.0);
        score += 5.0 * extra * (0.4 + 0.6 * progress);
    }

    if next > 0.0 && !is_new {
        if post == next {
            score -= 50.0;
        } else if post > next && post - next <= next / 4.0 {
            score -= 19.0;
        }
    }

    if !is_new && post > 0.0 {
        let unusable = if post < item.min(next.max(item)) {
            (item.min(next.max(item)) - post) / capacity
        } else {
            0.0
        };
        score += 52.0 * unusable;
    }

    let lookahead_fit = if next > 0.0 && post + 1e-9 >= next {
        1.0 - (post - next) / capacity
    } else if next > 0.0 {
        -1.0 + next / capacity
    } else {
        0.0
    };
    score -= 9.0 * lookahead_fit * (0.45 + 0.55 * progress);

    let utilization_gap = (norm_post - norm_mean).clamp(-1.0, 1.0);
    score += 7.0 * utilization_gap * utilization_gap * progress * progress;

    score
}

