        } else {
            0.0
        };
        score -= 25.0 * closure * (0.45 + 0.55 * progress);

        let residual_mod = post % nxt;
        if residual_mod <= nxt * 0.12 {
            score -= 8.0 * (0.5 + 0.5 * progress);
        }
    }

    score
