pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items == 0 { 0.0 } else { step_index as f64 / total_items as f64 };

    // A new bin is useful immediately, but becomes more attractive as the
    // stream approaches its end and old bins become difficult to fill.
    if is_new_bin {
        let last_chance_penalty = if fitting_bins_count <= 1 { 35.0 } else { 0.0 };
        let end_urgency = 18.0 * progress;
        score += 42.0 - last_chance_penalty - end_urgency;
    } else {
        // Reward placements whose remaining capacity can absorb the known
        // next item, especially when this is the final useful placement.
        if next_item_size > 0 && post_residual >= next_item_size {
            let exact_match = if post_residual == next_item_size { 1.0 } else { 0.0 };
            score -= 22.0 + 10.0 * exact_match;
        }

        // Strongly penalize residual space too small for the next item: it
        // is likely dead space and encourages opening a fresh bin later.
        if next_item_size > 0 && post_residual < next_item_size {
            let shortfall = (next_item_size - post_residual) as f64;
            score += 2.2 * shortfall;
        }

        // Relative residual occupancy is a proxy for how well this bin
        // participates in the remaining stream. Below-average residual is
        // preferred, while very large residual indicates a weak fit.
        let residual_ratio = post_residual as f64 / bin_capacity.max(1) as f64;
        let mean_ratio = (mean_residual / bin_capacity.max(1) as f64).clamp(0.0, 1.0);
        score += 70.0 * (residual_ratio - mean_ratio);

        // Reward tight fits and avoid creating many fragmented bins.
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= 8.0 * fill_ratio.clamp(0.0, 1.0);

        // If this is the last bin able to hold the current item, opening a
        // new one is less desirable than using it here.
        if fitting_bins_count == 1 {
            score -= 14.0;
        }
    }

    // Slightly prefer existing bins when there are many alternatives, but
    // retain the lookahead benefit of a new bin when necessary.
    if !is_new_bin && open_bins_count > 1 {
        score += 1.5 * (open_bins_count as f64 - 1.0).min(8.0);
    }

    score
}

