        score += 40.0 * (post / capacity).powi(2) * (0.55 + 0.45 * progress);
    }

    if !is_new && post > 0.0 {
        let rem = post % next;
        let residue_cost = if rem == 0.0 {
            0.0
        } else if rem <= next / 4.0 {
            0.42
        } else if rem >= next * 0.75 {
            0.84
        } else {
            1.0
        };
        score += 32.0 * residue_cost * (1.0 - 0.35 * progress);

        let after = post - next;
        if after > 0.0 {
            let second_rem = after % item;
            if second_rem == 0.0 {
                score -= 19.0 * (0.45 + 0.55 * progress);
            } else {
                let sliver = second_rem.min(item - second_rem) / item;
                score += 31.0 * sliver * (0.4 + 0.6 * progress);
            }
        }

        let closure = if (post - next).abs() < 0.5 {
            1.0
        } else if (post - next).abs() <= item * 0.15 {
            0.55
        } else {
            0.0
        };
        score -= 28.0 * closure * (0.45 + 0.55 * progress);

        if rem <= next * 0.12 {
            score -= 9.0 * (0.5 + 0.5 * progress);
        }
    }

    if !is_new && post > 0.0 && next > 0.0 {
        let after_next = (post - next).max(0.0);
        let next_waste = if after_next == 0.0 {
            0.0
        } else {
            let rem = after_next % item;
            rem.min(item - rem) / item
        };
        let chain = if post >= next { 1.0 } else { post / next };
        score -= 36.0 * chain * (0.45 + 0.55 * progress);
        score += 50.0 * next_waste * (0.45 + 0.55 * progress);

        let second = if after_next >= item {
            after_next - item
        } else if after_next >= next.min(item) {
            0.0
        } else {
            after_next
        };
        let second_utility = if after_next >= item {
            1.0
        } else {
            second / item
        };
        score -= 29.0 * second_utility * (0.35 + 0.65 * late);
    }

    if is_new && fitting_bins_count > 0 {
        let tight = (fitting_bins_count as f64).min(4.0) / 4.0;
        score += 50.0 * tight * (1.0 - 0.52 * progress);
        score -= 20.0 * nitem * nitem * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity.max(1) as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let residual = bin_residual as f64;
    let mean = mean_residual.max(0.0).min(capacity);
    let progress = if total_items == 0 {
        0.0
    } else {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    };
    let is_new = bin_residual == bin_capacity;
    let norm_post = (post / capacity).clamp(0.0, 1.0);
    let norm_item = (item / capacity).clamp(0.0, 1.0);
    let norm_mean = (mean / capacity).clamp(0.0, 1.0);
    let norm_next = (next / capacity).clamp(0.0, 1.0);
    let fitting_ratio = (fitting_bins_count as f64 / open_bins_count.max(1) as f64).clamp(0.0, 1.0);

    let mut score = post;

    if post_residual == 0 {
        score -= 264.0 + 94.0 * progress + 47.0 * norm_item;
    } else {
        score += 125.0 * norm_post * (1.0 - 0.41 * progress);

        if next > 0.0 {
            if post >= next {
                let alignment = 1.0 - (post - next) / capacity;
                score -= 49.0 * alignment;
                let remainder = post % next;
                if remainder == 0.0 {
                    score -= 35.0;
                } else if remainder <= next / 3.0 {
                    score -= 18.0;
                }
            } else {
                let deficit = (next - post) / next;
                score += 21.0 * deficit * deficit;
            }
        }

        if post < item {
            score += 104.0 * (item - post) / capacity;
        } else {
            score -= 21.0 * (post / item.max(1.0)).min(8.0);
            let remainder = post % item.max(1.0);
            if remainder == 0.0 {
                score -= 30.0;
            } else if remainder <= item / 3.0 {
                score -= 14.0;
            }
        }

        let gap = (norm_post - norm_mean).clamp(-1.0, 1.0);
        score += 37.0 * gap * gap * (0.34 + 0.66 * progress);
        score += 27.0 * norm_post * (1.0 - progress) * (1.0 - norm_mean);

        if next > 0.0 {
            let distance = (post - next).abs() / capacity;
            score += 28.0 * distance;
        }
    }

    if is_new {
        score += 59.0 + 85.0 * progress + 40.0 * fitting_ratio + 29.0 * norm_item;
        if progress > 0.84 && fitting_bins_count > 1 {
            score += 46.0;
        }
        if fitting_bins_count == 0 {
            score -= 80.0;
        }
        // NEW-BIN GUARD: opening a fresh bin only makes sense when existing options are
        // genuinely poor. Require a meaningful dead-space burden before allowing a new bin
        // to win, and never open one when an exact/near-exact fit exists.
        if fitting_bins_count > 0 {
            // estimate best available dead space among fitting bins is unavailable here, so
            // use the global mean residual as a proxy for the quality of open options.
            let pooled_dead = (mean % item.max(1.0)).min(item.max(1.0) - (mean % item.max(1.0))) / item.max(1.0);
            score += 26.0 * pooled_dead * (0.5 + 0.5 * progress);
        }
    }

    score -= 38.0 * norm_mean * norm_item;
    score += 17.0 * progress * (1.0 - norm_mean);

    if fitting_bins_count == 1 && !is_new {
        score += 26.0 + 65.0 * progress + 2.3 * post;
        if post > 0.0 && post < next {
            score += 20.0;
        }
    }

    if open_bins_count > 2 && !is_new {
        let extra = (open_bins_count as f64 - 2.0).min(6.0);
        score += 5.3 * extra * (0.4 + 0.6 * progress);
    }

    if next > 0.0 && !is_new {
        if post == next {
            score -= 60.0;
        } else if post > next && post - next <= next / 4.0 {
            score -= 24.0;
        }
    }

    if !is_new && post > 0.0 {
        let reference = item.min(next.max(item));
        if post < reference {
            score += 79.0 * (reference - post) / capacity;
        }

        if post < item {
            let dead_ratio = (item - post) / item;
            score += 125.0 * dead_ratio * dead_ratio;
        }

        if next > 0.0 && post < next {
            let fragmentation = (next - post) / next;
            score += 49.0 * fragmentation * fragmentation;
        }

        let remainder = post % item.max(1.0);
        let waste = remainder.min(item.max(1.0) - remainder) / item.max(1.0);
        score -= 17.0 * (1.0 - waste) * (0.35 + 0.65 * progress);

        let threshold = item.min(next.max(item)).min(0.35 * capacity);
        if post < threshold {
            let tiny_gap = (threshold - post) / threshold.max(1.0);
            score += 89.0 * tiny_gap * tiny_gap;
        }

        let usable = post.min(next.max(item));
        if usable > 0.0 {
            let unusable = (post - usable).max(0.0) / capacity;
            score += 47.0 * unusable * (0.55 + 0.45 * progress);
        }
    }

    let lookahead_fit = if next > 0.0 && post + 1e-9 >= next {
        1.0 - (post - next) / capacity
    } else if next > 0.0 {
        -1.0 + next / capacity
    } else {
        0.0
    };
    score -= 14.5 * lookahead_fit * (0.48 + 0.52 * progress);

    if !is_new && post > 0.0 {
        let reference = item.min(next.max(item));
        if post < reference {
            let small_gap = (reference - post) / capacity;
            score += 60.0 * small_gap * small_gap * fitting_ratio;
        }
    }

    if !is_new && residual > 0.0 {
        let old_remainder = residual % item.max(1.0);
        if old_remainder > 0.0 {
            let old_dead = old_remainder.min(item.max(1.0) - old_remainder) / item.max(1.0);
            score += 34.0 * old_dead * (0.45 + 0.55 * progress);
        }

        let bin_fill = 1.0 - residual / capacity;
        let pooled_fill = 1.0 - norm_mean;
        let fill_gap = (bin_fill - pooled_fill).clamp(-1.0, 1.0);
        score -= 21.0 * fill_gap * fill_gap * (1.0 - 0.45 * progress);
    }

    if !is_new && post > 0.0 && next > 0.0 {
        let next_after = post - next;
        if next_after > 0.0 {
            let old_mod = residual % next;
            let projected = next_after % next;
            let disruption = if old_mod == 0.0 {
                (projected as f64 / next).min(1.0)
            } else {
                (projected as f64 - old_mod as f64).abs() / next
            };
            score += 33.0 * disruption * (0.45 + 0.55 * progress);
        }
    }

    if !is_new && post > 0.0 && next > 0.0 && post >= next {
        let residual_after_next = post - next;
        let blocked = if residual_after_next < item {
            (item - residual_after_next) / item
        } else {
            0.0
        };
        score += 68.0 * blocked * blocked * (0.55 + 0.45 * progress);
    }

    // ---- NEW: dead-space dominance term -------------------------------------
    // Compare the dead space (unusable slack) left in this bin after placing the item
    // against the residual space of the bin before placement. Bin residual space
    // balance: prefer bins whose leftover slack matches the pooled mean slack.
    if !is_new {
        let slack_after = post;
        // slack that cannot be used by the *next* observed item
        let blocked_slack = if next > 0.0 && slack_after < next {
            (next - slack_after) / capacity
        } else {
            0.0
        };
        // how much of this bin's residual space is "stranded" (below the smallest
        // plausible item): estimate with a fraction of the item size
        let stranded = if slack_after > 0.0 {
            let r = slack_after % item.max(1.0);
            if r == 0.0 { 0.0 } else { r.min(item.max(1.0) - r) / item.max(1.0) }
        } else {
            0.0
        };
        let dead_total = (0.55 * stranded + 0.45 * blocked_slack).clamp(0.0, 1.0);
        // reward low dead space, weighted more strongly as packing progresses
        score -= 30.0 * dead_total * (0.4 + 0.6 * progress);
        // dead space relative to the pooled average slack level
        let rel_dead = (norm_post - norm_mean).abs();
        score -= 12.0 * rel_dead * (0.5 + 0.5 * progress) * (1.0 - norm_mean);
    }

    // ---- NEW: fill-level targeting ------------------------------------------
    // Encourage placing items into bins whose fill level is close to a target that
    // rises with progress (tighten the bins as we go). Non-linear near target.
    if !is_new {
        let bin_fill = 1.0 - norm_post;
        let target = 0.55 + 0.35 * progress;
        let dev = (bin_fill - target).abs();
        // asymmetric: undershoot (bin still loose) is worse than overshoot late
        let weight = if bin_fill < target { 1.0 } else { 0.55 };
        score += 24.0 * dev * dev * weight * (0.5 + 0.5 * progress);
    }

    // ---- NEW: exact / near-exact closing bonus ------------------------------
    if !is_new && post > 0.0 {
        let near = (post - item).abs();
        if near <= 1.0 + 1e-9 {
            score -= 45.0 + 30.0 * progress;
        } else if near <= 3.0 + 1e-9 {
            score -= 18.0 * (1.0 - (near - 1.0) / 2.0);
        }
        // binary-friendly: small residual left means likely bin can be closed soon
        if post <= 0.12 * capacity && post >= item {
            score -= 14.0 * (0.5 + 0.5 * progress);
        }
    }

    // ---- NEW: pressure term --------------------------------------------------
    // When many bins are open, spread items to avoid stranding; but when the pool is
    // nearly homogeneous, concentrate to close bins fast.
    if !is_new && open_bins_count > 1 {
        let conc = if norm_post < 0.25 { 1.0 } else { 0.0 };
        score -= 9.0 * conc * (1.0 - fitting_ratio) * progress;
    }

    score
}
